def bank_rollback(balance, transactions):
    """
    Apply transactions sequentially to the given balance.
    If at any point the balance becomes negative, roll back and return (original_balance, False).
    Otherwise, return (final_balance, True).
    """
    current_balance = balance
    for transaction in transactions:
